<script lang="ts">
  import { CONTROL_TYPES, DEFAULT_AI_LAYOUT, FIELD_WIDTHS, FORMAT_TYPES, OPTION_SOURCES, REFERENCE_KINDS, allLayoutFields, cloneAiLayout, displayBinding, layoutErrors, newLayoutId, type AiLayout, type AiLayoutBlock, type AiLayoutField, type AiLayoutGroup, type AiLayoutRepeater, type AiLayoutTab } from '../ai-layout';

  let { layout, onChange, onSave, onReload }: { layout:AiLayout; onChange:(layout:AiLayout)=>void; onSave:()=>void; onReload:()=>void } = $props();
  type Selection={kind:'tab'|'block'|'group'|'field';id:string};
  type DragItem={kind:'tab'|'block'|'field';id:string};
  type DropTarget={kind:'tab'|'block'|'group'|'field';id:string;after:boolean};
  let selected=$state<Selection>({kind:'tab',id:localStorage.getItem('mech-reader-layout-dev:tab')??DEFAULT_AI_LAYOUT.tabs[0]?.id??''});let drag=$state<DragItem|null>(null);let pendingDrag=$state<DragItem|null>(null);let dragOrigin={x:0,y:0};let dropTarget=$state<DropTarget|null>(null);let history=$state<AiLayout[]>([cloneAiLayout(DEFAULT_AI_LAYOUT)]);let historyIndex=$state(0);
  let activeTabId=$derived(selected.kind==='tab'?selected.id:tabContaining(selected.id)?.id??layout.tabs[0]?.id??'');
  let activeTab=$derived(layout.tabs.find(tab=>tab.id===activeTabId)??layout.tabs[0]);
  let errors=$derived(layoutErrors(layout));
  let bindingOptions=$derived([...new Set(['name','record','record[0]','record[1][0]','record[1][1]','record[1][2]','record[2]','record[3]',...allLayoutFields(layout).map(field=>field.binding)])].sort());

  function tabContaining(id:string):AiLayoutTab|undefined{return layout.tabs.find(tab=>tab.id===id||tab.blocks.some(block=>block.id===id||(block.type==='group'?block.fields.some(field=>field.id===id):block.groups.some(group=>group.id===id||group.fields.some(field=>field.id===id)))))}
  function blockById(id:string):AiLayoutBlock|undefined{return layout.tabs.flatMap(tab=>tab.blocks).find(block=>block.id===id)}
  function groupById(id:string):AiLayoutGroup|undefined{for(const block of layout.tabs.flatMap(tab=>tab.blocks)){if(block.type==='group'&&block.id===id)return block;if(block.type==='repeater'){const group=block.groups.find(candidate=>candidate.id===id);if(group)return group}}}
  function fieldById(id:string):AiLayoutField|undefined{for(const block of layout.tabs.flatMap(tab=>tab.blocks)){const groups=block.type==='group'?[block]:block.groups;for(const group of groups){const field=group.fields.find(candidate=>candidate.id===id);if(field)return field}}}
  function selectedObject():AiLayoutTab|AiLayoutBlock|AiLayoutGroup|AiLayoutField|undefined {if(selected.kind==='tab')return layout.tabs.find(tab=>tab.id===selected.id);if(selected.kind==='block')return blockById(selected.id);if(selected.kind==='group')return groupById(selected.id);return fieldById(selected.id)}
  function commit(change:(draft:AiLayout)=>void){const draft=cloneAiLayout(layout);change(draft);onChange(draft);history=history.slice(0,historyIndex+1);history.push(cloneAiLayout(draft));historyIndex=history.length-1}
  function undo(){if(historyIndex<=0)return;historyIndex--;onChange(cloneAiLayout(history[historyIndex]))}
  function redo(){if(historyIndex>=history.length-1)return;historyIndex++;onChange(cloneAiLayout(history[historyIndex]))}
  function mutateSelected(key:string,value:unknown){commit(draft=>{const target=findObject(draft,selected.id);if(target)(target as Record<string,unknown>)[key]=value})}
  function findObject(draft:AiLayout,id:string):object|undefined{for(const tab of draft.tabs){if(tab.id===id)return tab;for(const block of tab.blocks){if(block.id===id)return block;const groups=block.type==='group'?[block]:block.groups;for(const group of groups){if(group.id===id)return group;const field=group.fields.find(candidate=>candidate.id===id);if(field)return field}}}}
  function select(kind:Selection['kind'],id:string){selected={kind,id};const tab=tabContaining(id)??(kind==='tab'?layout.tabs.find(candidate=>candidate.id===id):undefined);if(tab)localStorage.setItem('mech-reader-layout-dev:tab',tab.id)}
  function addTab(){const id=newLayoutId('tab');commit(draft=>draft.tabs.push({id,title:'New tab',description:'',blocks:[]}));select('tab',id)}
  function addGroup(){if(!activeTab)return;const id=newLayoutId('group');commit(draft=>draft.tabs.find(tab=>tab.id===activeTab.id)?.blocks.push({id,type:'group',title:'New group',description:'',columns:2,fields:[]}));select('block',id)}
  function addRepeater(){if(!activeTab)return;const id=newLayoutId('repeater'),groupId=newLayoutId('group');commit(draft=>draft.tabs.find(tab=>tab.id===activeTab.id)?.blocks.push({id,type:'repeater',title:'New repeater',description:'',binding:'tag:vlist',itemLength:1,itemLabel:'Item',addLabel:'Add item',groups:[{id:groupId,type:'group',title:'Fields',description:'',columns:2,fields:[]}]}));select('block',id)}
  function addNestedGroup(repeater:AiLayoutRepeater){const id=newLayoutId('group');commit(draft=>{const target=findObject(draft,repeater.id) as AiLayoutRepeater|undefined;target?.groups.push({id,type:'group',title:'New group',description:'',columns:2,fields:[]})});select('group',id)}
  function addField(group?:AiLayoutGroup){const target=group??(selected.kind==='group'?groupById(selected.id):selected.kind==='block'&&blockById(selected.id)?.type==='group'?blockById(selected.id) as AiLayoutGroup:undefined);if(!target)return;const id=newLayoutId('field');const insideRepeater=layout.tabs.some(tab=>tab.blocks.some(block=>block.type==='repeater'&&block.groups.some(candidate=>candidate.id===target.id)));commit(draft=>{const destination=findObject(draft,target.id) as AiLayoutGroup|undefined;destination?.fields.push({id,label:'New field',description:'',binding:insideRepeater?'item[0]':'record[0]',control:'text',format:'auto',width:'normal'})});select('field',id)}
  function removeSelection(){if(layout.tabs.length===1&&selected.kind==='tab')return;if(!window.confirm('Delete the selected layout item and its contents?'))return;commit(draft=>{if(selected.kind==='tab'){draft.tabs=draft.tabs.filter(tab=>tab.id!==selected.id);return}for(const tab of draft.tabs){const blockIndex=tab.blocks.findIndex(block=>block.id===selected.id);if(blockIndex>=0){tab.blocks.splice(blockIndex,1);return}for(const block of tab.blocks){const groups=block.type==='group'?[block]:block.groups;const groupIndex=block.type==='repeater'?block.groups.findIndex(group=>group.id===selected.id):-1;if(groupIndex>=0){block.type==='repeater'&&block.groups.splice(groupIndex,1);return}for(const group of groups){const fieldIndex=group.fields.findIndex(field=>field.id===selected.id);if(fieldIndex>=0){group.fields.splice(fieldIndex,1);return}}}}});const tab=layout.tabs.find(candidate=>candidate.id===activeTabId)??layout.tabs[0];select('tab',tab?.id??'')}
  function moveArray<T>(list:T[],from:number,to:number){if(from<0||to<0||from===to)return;const [item]=list.splice(from,1);list.splice(to,0,item)}
  function beginPointerDrag(event:PointerEvent,item:DragItem){if(event.button!==0)return;pendingDrag=item;dragOrigin={x:event.clientX,y:event.clientY};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)}
  function targetAt(x:number,y:number):DropTarget|null{
    if(!drag)return null;let element=document.elementFromPoint(x,y) as HTMLElement|null;
    while(element){const kind=element.dataset.dropKind as DropTarget['kind']|undefined,id=element.dataset.dropId;if(kind&&id){const valid=drag.kind==='field'?(kind==='field'&&id!==drag.id)||kind==='group'||kind==='tab':drag.kind==='block'?(kind==='block'&&id!==drag.id)||kind==='tab':kind==='tab'&&id!==drag.id;if(valid){const rect=element.getBoundingClientRect();return {kind,id,after:y>rect.top+rect.height/2}}}element=element.parentElement}
    return null;
  }
  function pointerMove(event:PointerEvent){if(!pendingDrag)return;if(!drag&&Math.hypot(event.clientX-dragOrigin.x,event.clientY-dragOrigin.y)<5)return;if(!drag)drag=pendingDrag;dropTarget=targetAt(event.clientX,event.clientY);event.preventDefault()}
  function pointerEnd(event:PointerEvent){const wasDragging=!!drag;if(drag&&dropTarget){const target=dropTarget;if(target.kind==='tab')dropOnTab(target.id,target.after);else if(target.kind==='block')dropOnBlock(target.id,target.after);else if(target.kind==='group')dropOnGroup(target.id);else dropOnField(target.id,target.after)}pendingDrag=null;drag=null;dropTarget=null;if(wasDragging)event.preventDefault()}
  function cancelPointerDrag(){pendingDrag=null;drag=null;dropTarget=null}
  function nudge(direction:number){commit(draft=>{if(selected.kind==='tab'){const index=draft.tabs.findIndex(tab=>tab.id===selected.id);moveArray(draft.tabs,index,Math.max(0,Math.min(draft.tabs.length-1,index+direction)));return}for(const tab of draft.tabs){const blockIndex=tab.blocks.findIndex(block=>block.id===selected.id);if(blockIndex>=0){moveArray(tab.blocks,blockIndex,Math.max(0,Math.min(tab.blocks.length-1,blockIndex+direction)));return}for(const block of tab.blocks){const groups=block.type==='group'?[block]:block.groups;if(block.type==='repeater'){const groupIndex=block.groups.findIndex(group=>group.id===selected.id);if(groupIndex>=0){moveArray(block.groups,groupIndex,Math.max(0,Math.min(block.groups.length-1,groupIndex+direction)));return}}for(const group of groups){const fieldIndex=group.fields.findIndex(field=>field.id===selected.id);if(fieldIndex>=0){moveArray(group.fields,fieldIndex,Math.max(0,Math.min(group.fields.length-1,fieldIndex+direction)));return}}}}})}
  function extractBlock(draft:AiLayout,id:string):AiLayoutBlock|undefined{for(const tab of draft.tabs){const index=tab.blocks.findIndex(block=>block.id===id);if(index>=0)return tab.blocks.splice(index,1)[0]}}
  function extractField(draft:AiLayout,id:string):AiLayoutField|undefined{for(const tab of draft.tabs)for(const block of tab.blocks)for(const group of block.type==='group'?[block]:block.groups){const index=group.fields.findIndex(field=>field.id===id);if(index>=0)return group.fields.splice(index,1)[0]}}
  function dropOnTab(tabId:string,after=false){if(!drag)return;const dragged=drag;commit(draft=>{const target=draft.tabs.find(tab=>tab.id===tabId);if(!target)return;if(dragged.kind==='tab'){const from=draft.tabs.findIndex(tab=>tab.id===dragged.id);const [tab]=draft.tabs.splice(from,1);const targetIndex=draft.tabs.findIndex(tab=>tab.id===tabId);draft.tabs.splice(targetIndex+(after?1:0),0,tab)}else if(dragged.kind==='block'){const block=extractBlock(draft,dragged.id);if(block)target.blocks.push(block)}else{const field=extractField(draft,dragged.id);if(!field)return;let group=target.blocks.find(block=>block.type==='group') as AiLayoutGroup|undefined;if(!group){group={id:newLayoutId('group'),type:'group',title:'Fields',description:'',columns:2,fields:[]};target.blocks.push(group)}group.fields.push(field)}});drag=null}
  function dropOnBlock(blockId:string,after=false){if(!drag||drag.kind!=='block'||drag.id===blockId)return;const dragged=drag;commit(draft=>{const targetTab=draft.tabs.find(tab=>tab.blocks.some(block=>block.id===blockId));const block=extractBlock(draft,dragged.id);if(!targetTab||!block)return;const index=targetTab.blocks.findIndex(candidate=>candidate.id===blockId);targetTab.blocks.splice(index+(after?1:0),0,block)});drag=null}
  function dropOnGroup(groupId:string){if(!drag||drag.kind!=='field')return;const dragged=drag;commit(draft=>{const field=extractField(draft,dragged.id);const group=findObject(draft,groupId) as AiLayoutGroup|undefined;if(field&&group)group.fields.push(field)});drag=null}
  function dropOnField(fieldId:string,after=false){if(!drag||drag.kind!=='field'||drag.id===fieldId)return;const dragged=drag;commit(draft=>{const field=extractField(draft,dragged.id);if(!field)return;for(const tab of draft.tabs)for(const block of tab.blocks)for(const group of block.type==='group'?[block]:block.groups){const index=group.fields.findIndex(candidate=>candidate.id===fieldId);if(index>=0){group.fields.splice(index+(after?1:0),0,field);return}}});drag=null}
  function changeControl(value:string){commit(draft=>{const field=findObject(draft,selected.id) as AiLayoutField|undefined;if(!field)return;field.control=value as AiLayoutField['control'];if(value==='checkbox')field.format='boolean';if(value==='team'){field.binding='record[3]';field.format='integer';field.width='full'}if(value==='json'){field.binding='record';field.format='auto';field.width='full';field.readOnly=true}})}
  function optionsText(field:AiLayoutField):string{return (field.options??[]).map(option=>`${option.value} = ${option.label}`).join('\n')}
  function setOptions(text:string){mutateSelected('options',text.split(/\r?\n/).filter(line=>line.trim()).map(line=>{const split=line.indexOf('=');return split<0?{value:line.trim(),label:line.trim()}:{value:line.slice(0,split).trim(),label:line.slice(split+1).trim()}}))}
</script>

<datalist id="aiv-layout-bindings">{#each bindingOptions as binding}<option value={binding}></option>{/each}</datalist>
<div class="layout-editor-shell" role="application" class:pointer-dragging={!!drag} onpointermove={pointerMove} onpointerup={pointerEnd} onpointercancel={cancelPointerDrag}>
  <aside class="layout-tabs"><div class="layout-pane-title"><div><small>LAYOUT TREE</small><b>Tabs</b></div><button onclick={addTab}>＋</button></div><div class="layout-tab-list">{#each layout.tabs as tab (tab.id)}<button data-drop-kind="tab" data-drop-id={tab.id} class:active={activeTabId===tab.id} class:selected={selected.kind==='tab'&&selected.id===tab.id} class:drop-target={dropTarget?.kind==='tab'&&dropTarget.id===tab.id} class:drop-before={dropTarget?.kind==='tab'&&dropTarget.id===tab.id&&!dropTarget.after} class:drop-after={dropTarget?.kind==='tab'&&dropTarget.id===tab.id&&dropTarget.after} class:drag-source={drag?.kind==='tab'&&drag.id===tab.id} onpointerdown={event=>beginPointerDrag(event,{kind:'tab',id:tab.id})} onclick={()=>select('tab',tab.id)}><span>⋮⋮</span><b>{tab.title}</b><small>{tab.blocks.length}</small></button>{/each}</div><div class="layout-help">Drag tabs to reorder. Drop groups or fields on another tab to move them there.</div></aside>
  <main class="layout-canvas"><div class="layout-toolbar"><div><button onclick={undo} disabled={historyIndex===0}>Undo</button><button onclick={redo} disabled={historyIndex===history.length-1}>Redo</button><button onclick={()=>nudge(-1)}>Move up</button><button onclick={()=>nudge(1)}>Move down</button><button class="danger" onclick={removeSelection}>Delete</button></div><div><button onclick={addGroup}>Add group</button><button onclick={addRepeater}>Add repeater</button><button onclick={onReload}>Reload repository JSON</button><button class="primary" disabled={errors.length>0} onclick={onSave}>Save repository JSON</button></div></div>
    {#if errors.length}<div class="layout-error"><b>Layout cannot be saved or previewed:</b> {errors[0]}</div>{/if}
    {#if activeTab}<div class="layout-page"><div class="layout-page-heading" role="button" tabindex="0" class:selected={selected.kind==='tab'&&selected.id===activeTab.id} onclick={()=>select('tab',activeTab.id)} onkeydown={event=>{if(event.key==='Enter'||event.key===' ')select('tab',activeTab.id)}}><small>TAB</small><h1>{activeTab.title}</h1><p>{activeTab.description||'No tab description.'}</p></div>
      {#each activeTab.blocks as block (block.id)}<section class="layout-block" role="button" tabindex="0" data-drop-kind="block" data-drop-id={block.id} class:selected={selected.kind==='block'&&selected.id===block.id} class:drop-target={dropTarget?.kind==='block'&&dropTarget.id===block.id} class:drop-before={dropTarget?.kind==='block'&&dropTarget.id===block.id&&!dropTarget.after} class:drop-after={dropTarget?.kind==='block'&&dropTarget.id===block.id&&dropTarget.after} class:drag-source={drag?.kind==='block'&&drag.id===block.id} onpointerdown={event=>beginPointerDrag(event,{kind:'block',id:block.id})} onclick={event=>{event.stopPropagation();select('block',block.id)}} onkeydown={event=>{if(event.key==='Enter'||event.key===' ')select('block',block.id)}}><div class="layout-block-heading"><span>⋮⋮</span><div><small>{block.type.toUpperCase()}</small><h2>{block.title}</h2><p>{block.description||'No description.'}</p></div>{#if block.type==='repeater'}<button onclick={event=>{event.stopPropagation();addNestedGroup(block)}}>Add nested group</button>{/if}</div>
        {#if block.type==='group'}{@render Fields(block)}{:else}<div class="repeater-shell"><div class="repeater-label">Repeats from <code>{block.binding}</code> · {block.itemLabel}</div>{#each block.groups as group (group.id)}{@render Group(group)}{/each}</div>{/if}
      </section>{/each}
      {#if !activeTab.blocks.length}<div class="layout-empty" role="group" data-drop-kind="tab" data-drop-id={activeTab.id} class:drop-target={dropTarget?.kind==='tab'&&dropTarget.id===activeTab.id} class:drop-before={dropTarget?.kind==='tab'&&dropTarget.id===activeTab.id&&!dropTarget.after} class:drop-after={dropTarget?.kind==='tab'&&dropTarget.id===activeTab.id&&dropTarget.after}>Empty tab — add a group or drop one here.</div>{/if}
    </div>{/if}
  </main>
  <aside class="layout-inspector"><div class="layout-pane-title"><div><small>PROPERTIES</small><b>{selected.kind}</b></div></div>{#if selectedObject()}{@const target=selectedObject()!}<div class="inspector-form"><label><span>ID</span><input value={target.id} disabled></label>
    {#if selected.kind==='tab'}{@const tab=target as AiLayoutTab}<label><span>Tab title</span><input value={tab.title} oninput={event=>mutateSelected('title',event.currentTarget.value)}></label><label><span>Description</span><textarea oninput={event=>mutateSelected('description',event.currentTarget.value)}>{tab.description}</textarea></label>
    {:else if selected.kind==='field'}{@const field=target as AiLayoutField}<label><span>Label</span><input value={field.label} oninput={event=>mutateSelected('label',event.currentTarget.value)}></label><label><span>Description</span><textarea oninput={event=>mutateSelected('description',event.currentTarget.value)}>{field.description}</textarea></label><label><span>aiv.zrd binding</span><input list="aiv-layout-bindings" value={field.binding} oninput={event=>mutateSelected('binding',event.currentTarget.value)}></label><div class="inspector-two"><label><span>Control</span><select value={field.control} oninput={event=>changeControl(event.currentTarget.value)}>{#each CONTROL_TYPES as value}<option {value}>{value}</option>{/each}</select></label><label><span>Format</span><select value={field.format} oninput={event=>mutateSelected('format',event.currentTarget.value)}>{#each FORMAT_TYPES as value}<option {value}>{value}</option>{/each}</select></label></div><div class="inspector-two"><label><span>Width</span><select value={field.width} oninput={event=>mutateSelected('width',event.currentTarget.value)}>{#each FIELD_WIDTHS as value}<option {value}>{value}</option>{/each}</select></label><label><span>Precision</span><input type="number" min="0" max="12" value={field.precision??''} oninput={event=>mutateSelected('precision',event.currentTarget.value===''?undefined:Number(event.currentTarget.value))}></label></div><label class="check"><input type="checkbox" checked={field.readOnly??false} oninput={event=>mutateSelected('readOnly',event.currentTarget.checked)}> Read only</label><label><span>Option source</span><select value={field.optionSource??'none'} oninput={event=>mutateSelected('optionSource',event.currentTarget.value)}>{#each OPTION_SOURCES as value}<option {value}>{value}</option>{/each}</select></label><label><span>Reference source</span><select value={field.referenceKind??'none'} oninput={event=>mutateSelected('referenceKind',event.currentTarget.value)}>{#each REFERENCE_KINDS as value}<option {value}>{value}</option>{/each}</select></label><label><span>Static options <small>value = label</small></span><textarea class="options-editor" oninput={event=>setOptions(event.currentTarget.value)}>{optionsText(field)}</textarea></label>
    {:else if selected.kind==='block'&&(target as AiLayoutBlock).type==='repeater'}{@const repeater=target as AiLayoutRepeater}<label><span>Title</span><input value={repeater.title} oninput={event=>mutateSelected('title',event.currentTarget.value)}></label><label><span>Description</span><textarea oninput={event=>mutateSelected('description',event.currentTarget.value)}>{repeater.description}</textarea></label><label><span>List binding</span><input value={repeater.binding} oninput={event=>mutateSelected('binding',event.currentTarget.value)}></label><label><span>Item label</span><input value={repeater.itemLabel} oninput={event=>mutateSelected('itemLabel',event.currentTarget.value)}></label><label><span>Add button label</span><input value={repeater.addLabel} oninput={event=>mutateSelected('addLabel',event.currentTarget.value)}></label><label><span>New item length</span><input type="number" min="1" value={repeater.itemLength} oninput={event=>mutateSelected('itemLength',Number(event.currentTarget.value))}></label>
    {:else}{@const group=target as AiLayoutGroup}<label><span>Title</span><input value={group.title} oninput={event=>mutateSelected('title',event.currentTarget.value)}></label><label><span>Description</span><textarea oninput={event=>mutateSelected('description',event.currentTarget.value)}>{group.description}</textarea></label><div class="inspector-two"><label><span>Columns</span><select value={group.columns} oninput={event=>mutateSelected('columns',Number(event.currentTarget.value))}><option value="1">1</option><option value="2">2</option><option value="3">3</option></select></label><label><span>Optional tag</span><input value={group.presenceTag??''} oninput={event=>mutateSelected('presenceTag',event.currentTarget.value||undefined)}></label></div><button onclick={()=>addField(group)}>Add field to group</button>{/if}
  </div>{:else}<div class="layout-help">Select a tab, group, repeater, or field.</div>{/if}</aside>
</div>

{#snippet Group(group:AiLayoutGroup)}
  <div class="designer-group" role="button" tabindex="0" data-drop-kind="group" data-drop-id={group.id} class:selected={selected.kind==='group'&&selected.id===group.id} class:drop-target={dropTarget?.kind==='group'&&dropTarget.id===group.id} class:drop-before={dropTarget?.kind==='group'&&dropTarget.id===group.id&&!dropTarget.after} class:drop-after={dropTarget?.kind==='group'&&dropTarget.id===group.id&&dropTarget.after} onclick={event=>{event.stopPropagation();select('group',group.id)}} onkeydown={event=>{if(event.key==='Enter'||event.key===' ')select('group',group.id)}}>{@render GroupHeader(group)}{@render Fields(group)}</div>
{/snippet}

{#snippet GroupHeader(group:AiLayoutGroup)}
  <div class="designer-group-heading"><div><small>GROUP · {group.columns} COLUMN{group.columns===1?'':'S'}{#if group.presenceTag} · OPTIONAL {group.presenceTag}{/if}</small><h3>{group.title}</h3><p>{group.description||'No description.'}</p></div><button onclick={event=>{event.stopPropagation();addField(group)}}>Add field</button></div>
{/snippet}

{#snippet Fields(group:AiLayoutGroup)}
  <div class="designer-fields columns-{group.columns}">{#each group.fields as field (field.id)}<button class="designer-field width-{field.width}" data-drop-kind="field" data-drop-id={field.id} class:selected={selected.kind==='field'&&selected.id===field.id} class:drop-target={dropTarget?.kind==='field'&&dropTarget.id===field.id} class:drop-before={dropTarget?.kind==='field'&&dropTarget.id===field.id&&!dropTarget.after} class:drop-after={dropTarget?.kind==='field'&&dropTarget.id===field.id&&dropTarget.after} class:drag-source={drag?.kind==='field'&&drag.id===field.id} onpointerdown={event=>{event.stopPropagation();beginPointerDrag(event,{kind:'field',id:field.id})}} onclick={event=>{event.stopPropagation();select('field',field.id)}}><span class="drag">⋮⋮</span><span><b>{field.label}</b><small>{field.control} · {field.format} · {displayBinding(field.binding)}</small><em>{field.description||'No description.'}</em></span></button>{/each}</div>{#if !group.fields.length}<div class="layout-empty" role="group" data-drop-kind="group" data-drop-id={group.id} class:drop-target={dropTarget?.kind==='group'&&dropTarget.id===group.id} class:drop-before={dropTarget?.kind==='group'&&dropTarget.id===group.id&&!dropTarget.after} class:drop-after={dropTarget?.kind==='group'&&dropTarget.id===group.id&&dropTarget.after}>Drop fields here or add a field.</div>{/if}
{/snippet}

<style>
